INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N100-01','CN0214','W05S04','共享站历史工艺','3.19.1 p76–79','政府同文档备用入口 https://www.zjwy.gov.cn/module/download/downfile.jsp?classid=0&filename=77329421ed7741b492043b197dfee1de.pdf 。含氟300t/d、脱氯10t/d均能力；氯仿去除报告称90%以上，非本轮实测。详述生活A/O、概述接触氧化，未判差异。截图受阻正文可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N100-02','CN0214','W05S04','历史排口自行监测','表3.19-1','2023自动355、SS手工4、AOX手工2；六因子与流量最小最大平均；流量单位不清，零值照录，超标0；非专线水质。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N100-03','CN0214','W05S04','新项目设计残余物及投资','表4.4-8/12 p88','含氨废水处理残渣802.67t/a、污泥10t/a，HW49 772-006-49，残渣氯化钠及重金属，资质单位处置；非实际；总投资5500万元环保290万元。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N100-04','CN0214','W05S06','募投原公告','2026-04-25董事会，4-28公告p2–3','3-31募资实际3653.44万元，计划5500，占66.43%；剩余1900.85含收益54.28，尚待支付576.13；建成达到预定可使用状态，非环保验收；半年报另存。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N100-05','CN0302','turn787991search0','许可地址及状态纠正','2026-11-06持证名单','正式证LN2110040046，地址宏伟区东环路3号；旧南七路6号，关系待核，未证实搬迁；不重复400/500许可记录或证明经营。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N100-06','CN0070','S100-01','再生现场及生产线成本边界','2026-09-02现场报道','超声清洗、化学洗、活化液浸润、煅烧；科研团队称去中间热处理、水基清洗活化使生产线成本下降20–30%，非吨水成本；基线未披露。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N100-07','CN0248','S100-02','历史生产调试','2025半年报经营讨论','公司称新疆项目2025年6月生产调试；不证明新增万吨达产、实际RO运行或2026状态。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
